    // ═══════════════════════════════════════════════════════════
    // §260. v0.9.1312 — Vault Cleanup: Brad's three decisions, guarded.
    //
    //   Merge the doubled 20-93699, remove ONLY verifiably-empty leftovers
    //   (2205 never referenced), migrate the legacy vault, rename ARCHIVE.
    //   The REAL preview + run execute against a MUTABLE fake Drive.
    // ═══════════════════════════════════════════════════════════
    section('260. Vault Cleanup: preview plans, run moves, trash only what is empty');
    await (async function () {
      const p60 = require('path');
      const tl60 = fs.readFileSync(p60.join(__dirname, '..', 'app', 'tools.js'), 'utf8');
      const v0 = tl60.indexOf('var _vcPlan = null;');
      const v1 = tl60.indexOf("if (typeof window !== 'undefined') {\n  window.rrVaultCleanupPreview");
      ok('260 the cleanup source slice was found', v0 > 0 && v1 > v0);
      // ── a mutable fake Drive ──
      const F = {};   // id -> {name, parent, folder, trashed}
      function add(id, name, parent, folder) { F[id] = { name, parent, folder: !!folder, trashed: false }; }
      add('ROOT', 'My Collection Photos', null, true);
      add('SOLD', 'My Sold Collection Photos', null, true);
      add('TWIN', 'mth No. 20-93699', 'ROOT', true);
      add('T3', '3', 'TWIN', true); add('T3F', 'RSV.png', 'T3', false);
      add('T4', '4', 'TWIN', true); add('T4F', 'RSV.png', 'T4', false);
      add('MTHO', 'MTH O', 'ROOT', true);
      add('TGT', '20-93699', 'MTHO', true);
      add('G4', '4', 'TGT', true); add('G4F', 'RSV.png', 'G4', false);
      add('G5', '5', 'TGT', true);
      add('E1', '84631', 'MPC', true);
      add('E2', '84631-BOX', 'MPC', true); add('E2F', 'straggler.jpg', 'E2', false);   // NOT empty → left alone
      add('E3', '0028CC', 'ROOT', true);
      add('ATLAS', 'Atlas O', 'ROOT', true); add('K2205', '2205', 'ATLAS', true);      // must never be touched
      add('LEG', 'Lionel Vault - My Collection', null, true);
      add('L2056', '2056', 'LEG', true); add('L2056F', 'a.jpg', 'L2056', false);
      add('L726', '726', 'LEG', true); add('L726F', 'b.jpg', 'L726', false);
      add('L736', '736', 'LEG', true); add('L736F', 'c.jpg', 'L736', false);
      add('LPDF', 'Collection Share 03-14-2026.pdf', 'LEG', false);
      add('PWERA', 'Lionel Postwar', 'ROOT', true);
      add('A726', '726', 'PWERA', true); add('A726F', 'RSV.png', 'A726', false);
      const patched = [];
      const fakeDrive = async function (method, endpoint, body) {
        if (method === 'GET') {
          const q = decodeURIComponent(endpoint.split('?q=')[1].split('&')[0]);
          const mParent = q.match(/'([^']+)' in parents/);
          const mName = q.match(/name='([^']+)'/);
          const files = Object.keys(F).filter((id) => {
            const f = F[id];
            if (f.trashed) return false;
            if (mParent && f.parent !== mParent[1]) return false;
            if (mName && f.name !== mName[1]) return false;
            if (!mParent && !mName) return false;
            if (/mimeType='application\/vnd\.google-apps\.folder'/.test(q) && !f.folder) return false;
            return true;
          }).map((id) => ({ id, name: F[id].name, parents: [F[id].parent], mimeType: F[id].folder ? 'application/vnd.google-apps.folder' : 'image/png' }));
          return { files };
        }
        if (method === 'PATCH') {
          patched.push({ endpoint, body });
          const id = endpoint.split('/files/')[1].split('?')[0];
          const mv = endpoint.match(/addParents=([^&]+)&removeParents=([^&]+)/);
          if (mv) F[id].parent = mv[1];
          if (body && body.trashed) F[id].trashed = true;
          if (body && body.name) F[id].name = body.name;
          return {};
        }
        return {};
      };
      const out60 = { innerHTML: '' };
      const store = { 'lv_photos_id': 'ROOT', 'lv_sold_photos_id': 'SOLD' };
      const env = {
        driveRequest: fakeDrive,
        document: { getElementById: (id) => (id === 'vault-cleanup-results' ? out60 : null) },
        localStorage: { getItem: (k) => store[k] || null, setItem: (k, v) => { store[k] = v; }, removeItem: () => {} },
        rrEsc: (s) => String(s == null ? '' : s),
        driveCache: { photosId: 'ROOT', soldPhotosId: 'SOLD' },
        buildToolsPage: () => {},
        window: {},
      };
      const api60 = new Function('driveRequest', 'document', 'localStorage', 'rrEsc', 'driveCache', 'buildToolsPage', 'window',
        tl60.slice(v0, v1) + '\nreturn { preview: rrVaultCleanupPreview, run: rrVaultCleanupRun, plan: function(){ return _vcPlan; }, setPlan: function(p){ _vcPlan = p; } };')(
        env.driveRequest, env.document, env.localStorage, env.rrEsc, env.driveCache, env.buildToolsPage, env.window);
      await api60.preview();
      const plan = api60.plan();
      const labels = plan.map((s) => s.label).join('\n');
      const ids = plan.map((s) => s.id);
      ok('260 the twin merges: inv 3 moves whole, inv 4 merges file-by-file then goes',
         ids.includes('T3') && ids.includes('T4F') && ids.includes('T4') &&
         plan.find((s) => s.id === 'T3').act === 'reparent' &&
         plan.find((s) => s.id === 'T4').act === 'trash-empty');
      ok('260 the twin folder itself is trashed only AFTER its contents move',
         plan.findIndex((s) => s.id === 'TWIN') > plan.findIndex((s) => s.id === 'T3'));
      ok('260 only the EMPTY leftovers are planned — the straggler folder is left alone',
         ids.includes('E1') && ids.includes('E3') && !ids.includes('E2') &&
         /not empty any more/.test(out60.innerHTML));
      ok('260 2205 is never referenced by any step', !ids.includes('K2205') && !/2205/.test(labels));
      ok('260 the legacy vault: whole-folder moves, a merge for the active twin, 736 to Sold',
         plan.find((s) => s.id === 'L2056' && s.to === 'PWERA') &&
         plan.find((s) => s.id === 'L726F' && s.to === 'A726') &&
         plan.find((s) => s.id === 'L736' && s.to === 'SOLD') &&
         plan.find((s) => s.id === 'LEG' && s.act === 'rename' && /ARCHIVE/.test(s.name)));
      ok('260 the share PDF stays in the archive', !ids.includes('LPDF'));
      // ── run it, plus one poisoned step to prove the trash guard ──
      const poisoned = plan.concat([{ act: 'trash-empty', id: 'ATLAS', label: 'poison: trash a non-empty folder' }]);
      api60.setPlan(poisoned);
      await api60.run();
      ok('260 every real step lands: files moved, twin trashed, vault renamed ARCHIVE',
         F['T3'].parent === 'TGT' && F['T4F'].parent === 'G4' && F['TWIN'].trashed &&
         F['L2056'].parent === 'PWERA' && F['L726F'].parent === 'A726' && F['L736'].parent === 'SOLD' &&
         /^ARCHIVE/.test(F['LEG'].name));
      ok('260 the run-time guard refuses the poisoned trash — the folder survives',
         !F['ATLAS'].trashed && /poison/.test(out60.innerHTML) && /not empty/.test(out60.innerHTML));
      ok('260 a clean run would set the done flag; the poisoned one must NOT',
         store['rr_vault_cleanup_done'] !== '1');
      ok('260 empty leftovers really got trashed', F['E1'].trashed && F['E3'].trashed && !F['E2'].trashed);
    })();

    // ═══════════════════════════════════════════════════════════
    // §261. v0.9.1313 — the mirror describes THIS copy, not the first
    //        row that shares its number.
    //
    //   Found while checking 6050 var 9: Brad's read-only Sheet mirror
    //   labelled his two Savings Bank var 7 cars "Libby's Tomato Juice
    //   Boxcar" — _lookupMasterDesc resolved by NUMBER ONLY, and Libby's
    //   is the first 6050 row. Brad: "fix the other using inventory id."
    //   The REAL buildPersonalRow runs here.
    // ═══════════════════════════════════════════════════════════
    section('261. Mirror rows carry their OWN description (the 6050 Libby\'s label)');
    (function () {
      const p61 = require('path');
      const ap61 = fs.readFileSync(p61.join(__dirname, '..', 'app', 'app.js'), 'utf8');
      const c0 = ap61.indexOf("// v0.9.1313 (Brad's mirror labelled");
      const c1 = ap61.indexOf('\nif (typeof window !== \'undefined\') {\n  window.PERSONAL_SCHEMA');
      ok('261 the lookup + row-builder slice was found', c0 > 0 && c1 > c0);
      const HEADERS = ['Item Number', 'Variation', 'Master Description', 'Variation Description', 'Item Type', 'Road Name', 'Road Number', 'Manufacturer', 'Date Added', 'Matched Tender/Engine', 'Master Key', 'Era'];
      const IDX = { itemNum: 0, variation: 1, masterDescription: 2, variationDescription: 3, itemType: 4, roadName: 5, roadNumber: 6, manufacturer: 7, dateAdded: 8, matchedTo: 9, masterKey: 10, era: 11 };
      const CAT = [
        { key: 'pw|6050|1', itemNum: '6050', variation: '1', description: "Libby's Tomato Juice Boxcar", varDesc: 'TYPE 3 LIBBY', roadName: "Libby's" },
        { key: 'pw|6050|7', itemNum: '6050', variation: '7', description: 'Lionel Savings Bank Boxcar', varDesc: 'TYPE 1 BANK', roadName: 'Lionel Savings Bank' },
      ];
      const seenPrefer = [];
      const mk61 = new Function('PERSONAL_HEADERS', 'PERSONAL_FIELD_INDEX', '_isBoxItemNum', 'findMaster', 'rrMasterKeyOf', '_brandOfItem', 'Date',
        ap61.slice(c0, c1) + '\nreturn buildPersonalRow;');
      const build = mk61(
        HEADERS, IDX,
        () => false,
        function (num, vari, prefer) {
          seenPrefer.push(prefer || null);
          if (prefer && prefer.masterKey) { const hit = CAT.find((m) => m.key === prefer.masterKey); if (hit) return hit; }
          return CAT.find((m) => m.itemNum === String(num) && (!vari || String(m.variation) === String(vari)))
              || CAT.find((m) => m.itemNum === String(num)) || null;
        },
        (m) => m.key, () => '', function FakeDate() { return { toISOString: () => '2026-08-03T00:00:00Z' }; });
      // ── Brad's exact case: 6050 var 7 must read Savings Bank, never Libby's ──
      const row = build({ itemNum: '6050', variation: '7', era: 'pw', manufacturer: 'Lionel' });
      ok('261 the var 7 mirror row says Savings Bank — the Libby\'s label is dead',
         row[IDX.masterDescription] === 'Lionel Savings Bank Boxcar' &&
         row[IDX.variationDescription] === 'TYPE 1 BANK', JSON.stringify(row[IDX.masterDescription]));
      // ── the stored masterKey answers outright when the row carries one ──
      const row2 = build({ itemNum: '6050', variation: '', era: 'pw', manufacturer: 'Lionel', masterKey: 'pw|6050|7' });
      ok('261 a stored masterKey wins even with no variation on the row',
         row2[IDX.masterDescription] === 'Lionel Savings Bank Boxcar');
      ok('261 the lookups pass the copy\'s full identity (era, maker, masterKey)',
         seenPrefer.some((p) => p && p.era === 'pw' && p.manufacturer === 'Lionel' && 'masterKey' in p));
      // ── manual rows still never inherit catalog words ──
      const row3 = build({ itemNum: '6050', variation: '7', era: 'Manual' });
      ok('261 a manual row keeps its own words — no catalog description leaks in',
         row3[IDX.masterDescription] === '' && row3[IDX.variationDescription] === '');
    })();

    // ═══════════════════════════════════════════════════════════
    // §262. v0.9.1315 — change an item's variation after entry.
    //
    //   Brad, with his 3419 filed as var 1 that should be var 2: "we need
    //   to brainstorm how to change an item's variation number after it
    //   has already been entered… I put it in wrong, i went to the update
    //   info. No way to change it. This may cause issues, i don't know."
    //   The issues he sensed are exactly what these assertions pin.
    // ═══════════════════════════════════════════════════════════
    section('262. Update Info: the variation is changeable, identity follows');
    (function () {
      const p62 = require('path');
      const ac62 = fs.readFileSync(p62.join(__dirname, '..', 'app', 'app-collection.js'), 'utf8');
      ok('262 the picker exists for catalog items only, with 2+ variations, same era',
         /\(\(idx >= 0 && pd\.era !== 'Manual'\) \? \(function \(\) \{/.test(ac62) &&
         /if \(_vOpts\.length < 2\) return \[\];   \/\/ one variation = nothing to change/.test(ac62) &&
         /if \(item\._era && m\._era && m\._era !== item\._era\) return;   \/\/ same era only/.test(ac62));
      ok('262 the options carry value + description, never a bare typed number',
         /_vOpts\.push\(\{ v: v, t: 'Var ' \+ v \+ ' — ' \+ String\(m\.varDesc \|\| m\.description \|\| ''\)\.slice\(0, 70\) \}\)/.test(ac62) &&
         /const _ov = \(o && typeof o === 'object'\) \? o\.v : o;/.test(ac62));
      ok('262 the ORIGINAL variation is captured once, before any edit',
         /const _origVariation = String\(pd\.variation \|\| item\.variation \|\| ''\);/.test(ac62));
      ok('262 the PANEL save writes the USER\'s pick, not the master row the page opened on',
         /const _newVariation = String\(pd\.variation \|\| item\.variation \|\| ''\);/.test(ac62) &&
         // the v0.9.720 dateAdded comment is unique to the panel save — the
         // variation line inside THAT call must be the pick (other flows'
         // `item.variation` uses are their own business)
         /dateAdded: pd\.dateAdded \|\| '',   \/\/ v0\.9\.720[^]{0,200}variation: _newVariation,/.test(ac62));
      ok('262 a change re-derives the copy\'s stored identity — masterKey and both descriptions',
         /const _varChanged = _newVariation !== _origVariation;/.test(ac62) &&
         /pd\.masterKey = \(_nm && typeof rrMasterKeyOf === 'function'\) \? rrMasterKeyOf\(_nm\) : '';/.test(ac62) &&
         /pd\.masterDescription = \(_nm && _nm\.description\)/.test(ac62) &&
         /pd\.variationDescription = \(_nm && _nm\.varDesc\)/.test(ac62));
      ok('262 a For Sale listing of the SAME copy syncs in the same save — identity-checked, state only after the sheet says so',
         /state\.forSaleData\[pd\.inventoryId\]/.test(ac62) &&
         /\[_fs\.itemNum, _newVariation, _fs\.condition \|\| '', _fs\.askingPrice \|\| '',/.test(ac62) &&
         /\{ num: _fs\.itemNum \|\| '', invId: _fs\.inventoryId \|\| '' \}, 'For Sale list'\)\)/.test(ac62) &&
         /_fs\.variation = _newVariation;/.test(ac62));
      ok('262 after a change the page reopens on the NEW variation via the copy\'s id',
         /if \(_varChanged && pd\.inventoryId && typeof _openOwnedByInvId === 'function'\) \{\s*\n\s*_openOwnedByInvId\(pd\.inventoryId\);/.test(ac62) &&
         /'✓ Updated — now Var ' \+ _newVariation/.test(ac62));
      // The For Sale row rebuild must match the parser's column order exactly
      // (A–J: itemNum, variation, condition, askingPrice, dateListed, notes,
      // originalPrice, estWorth, inventoryId, manufacturer).
      const ad62 = fs.readFileSync(p62.join(__dirname, '..', 'app', 'app-data.js'), 'utf8');
      ok('262 the synced row and the parser agree on the column order',
         /_fs\.dateListed \|\| '', _fs\.notes \|\| '', _fs\.originalPrice \|\| '', _fs\.estWorth \|\| '',\s*\n\s*_fs\.inventoryId \|\| '', _fs\.manufacturer \|\| ''\]/.test(ac62) &&
         /condition: _s\(r\[2\]\), askingPrice: _s\(r\[3\]\), dateListed: _s\(r\[4\]\),\s*\n\s*notes: _s\(r\[5\]\), originalPrice: _s\(r\[6\]\), estWorth: _s\(r\[7\]\),/.test(ad62));
    })();

    // ═══════════════════════════════════════════════════════════
    // §263. v0.9.1316 — the search that "did not work" (it matched all).
    //
    //   Brad: "why does the text search not work" — 'helicopter'
    //   CONTAINS the alias keys co / ic / el, the substring rule expanded
    //   their groups, and the term 'co' matched nearly every description
    //   ("LOCOmotive", "SunoCO"), so the list never narrowed. The REAL
    //   _aliasSearch runs here with the REAL alias table.
    // ═══════════════════════════════════════════════════════════
    section('263. Search: alias keys expand on whole words, never fragments');
    (function () {
      const p63 = require('path');
      const bw63 = fs.readFileSync(p63.join(__dirname, '..', 'app', 'browse.js'), 'utf8');
      const cf63 = fs.readFileSync(p63.join(__dirname, '..', 'app', 'config.js'), 'utf8');
      // real alias table
      const gEq = cf63.indexOf('SEARCH_ALIAS_GROUPS = ');
      let gd = 0, gEnd = -1;
      for (let i = cf63.indexOf('[', gEq); i < cf63.length; i++) {
        if (cf63[i] === '[') gd++;
        else if (cf63[i] === ']') { gd--; if (!gd) { gEnd = i + 1; break; } }
      }
      const GROUPS = eval('(' + cf63.slice(cf63.indexOf('[', gEq), gEnd) + ')');
      const ALIASES = {};
      GROUPS.forEach((g) => { const t = g.map((x) => x.toLowerCase()); t.forEach((k) => { ALIASES[k] = t; }); });
      ok('263 the real alias table still carries the short keys that caused this',
         !!ALIASES['co'] && !!ALIASES['ic'] && !!ALIASES['el']);
      // real function
      const a0 = bw63.indexOf('function _aliasTermHit(');
      const a1 = bw63.indexOf('\nfunction populateFilters(');
      ok('263 the search slice was found', a0 > 0 && a1 > a0);
      const search = new Function('SEARCH_ALIASES', bw63.slice(a0, a1) + ' return _aliasSearch;')(ALIASES);
      // ── the bug, reproduced then dead ──
      ok('263 "helicopter" no longer matches the Sunoco tank car',
         search('2555 sunoco sunoco tank car tank', 'helicopter') === false);
      ok('263 "helicopter" still finds the helicopter flatcar',
         search('3419 helicopter launching flat car flatcar', 'helicopter') === true);
      ok('263 "helicopter" no longer matches a locomotive either — the "co" fragment is dead',
         search('2338 milwaukee road gp7 diesel locomotive', 'helicopter') === false);
      // The discriminating probe: the fragment-trigger must die on its own,
      // not hide behind the short-term rule. "helicopter" contains the key
      // "ic", whose LONG term "illinois central" would match this item —
      // only the whole-word trigger rule stops it.
      ok('263 a fragment-triggered group with a LONG matching term stays dead too',
         search('6250 illinois central gondola', 'helicopter') === false);
      // ── the shorthand the rule exists FOR still works ──
      ok('263 typing the alias itself still expands: "c&o" finds Chesapeake and Ohio',
         search('6462 chesapeake and ohio gondola', 'c&o') === true);
      ok('263 a whole-word key inside a longer query still expands',
         search('6462 chesapeake and ohio gondola', 'c&o gondola') === true);
      ok('263 the prefix direction survives: "fairbank" reaches its group',
         (function () {
           const fk = Object.keys(ALIASES).find((k) => k.includes('fairbank'));
           if (!fk) return true;   // group not in the table — nothing to prove
           return search('2321 ' + ALIASES[fk].join(' '), 'fairbank') === true;
         })());
      // ── short terms match whole words only ──
      ok('263 a short alias term never matches inside another word',
         search('sunoco tank', 'c&o') === false &&
         search('co gondola', 'c&o') === true);
    })();

    // ═══════════════════════════════════════════════════════════
    // §264. v0.9.1317 — the sales list a buyer can actually use.
    //
    //   Brad, reviewing his live sheet: "that is garbage." What a buyer
    //   used to get: "Gondola (var 2)", no notes (a SET sale read as one
    //   unit), no era, no contact, no photos. The REAL _sellSync runs
    //   here against a fake Sheets + Drive.
    // ═══════════════════════════════════════════════════════════
    section('264. Shareable For Sale sheet: contact, era, real words, notes, links');
    await (async function () {
      const p64 = require('path');
      const sl64 = fs.readFileSync(p64.join(__dirname, '..', 'app', 'sell.js'), 'utf8');
      const s0 = sl64.indexOf('async function _sellEnsureSheet');
      const s1 = sl64.indexOf('if (typeof window !== \'undefined\') window.rrSellSheetStartupSync');
      ok('264 the sync slice was found', s0 > 0 && s1 > s0);
      const written = { cleared: '', range: '', rows: null };
      const preferSeen = [];
      const opened = [];
      const env = {
        localStorage: { getItem: (k) => ({ rr_sell_sheet_id: 'SHEET1', rr_sell_contact: 'Brad Hale · 270-555 · bhale@…', rr_sell_photo_links: '1' }[k] || null), setItem: () => {} },
        driveRequest: async (m, ep) => (/files\/SHEET1/.test(ep) ? { id: 'SHEET1', trashed: false } : { files: [{ id: 'SHEET1' }] }),
        sheetsClear: async (id, r) => { written.cleared = r; },
        sheetsUpdate: async (id, r, rows) => { written.range = r; written.rows = rows; },
        _currencySymbol: () => '$',
        driveGetFolderPhotos: async (link) => ({ 'folder-good': [{ id: 'PH1' }], 'folder-locked': [{ id: 'PH2' }] }[link] || []),
        rrShareOpenPhoto: async (id) => { opened.push(id); return id === 'PH1'; },   // PH2 exists but REFUSES to open
        findMaster: (n, v, prefer) => { preferSeen.push(prefer); return ({
          '6462-50|2': { roadName: '', description: 'Gondola', varDesc: 'TYPE 2, RED SHELL UNPAINTED, WHITE LETTERING', itemType: 'Gondola' },
          '205-P|2': { roadName: 'Missouri Pacific', description: 'Alco Diesel', varDesc: 'light blue shell painted blue with white heat stamped lettering', itemType: 'Diesel Locomotive' },
        })[String(n) + '|' + String(v)] || null; },
        ERAS: { pw: { label: 'Lionel Postwar' } },
        state: {
          forSaleData: {
            a: { inventoryId: 'a', itemNum: '205-P', variation: '2', condition: '7', askingPrice: '150', notes: 'Set sale: 205-P, 205-D' },
            b: { inventoryId: 'b', itemNum: '6462-50', variation: '2', condition: '7', askingPrice: '25', notes: '' },
            c: { inventoryId: 'c', itemNum: '6656', variation: '4', condition: '7', askingPrice: '20', notes: '' },
          },
          personalData: {
            a: { inventoryId: 'a', itemNum: '205-P', variation: '2', era: 'pw', manufacturer: 'Lionel', masterKey: 'pw|205|2', hasBox: 'No', photoItem: 'folder-good' },
            b: { inventoryId: 'b', itemNum: '6462-50', variation: '2', era: 'pw', manufacturer: 'Lionel', hasBox: 'Yes', photoItem: 'folder-empty' },
            c: { inventoryId: 'c', itemNum: '6656', variation: '4', era: 'pw', manufacturer: 'Lionel', hasBox: 'No', photoItem: 'folder-locked' },
          },
        },
      };
      const api64 = new Function('localStorage', 'driveRequest', 'sheetsClear', 'sheetsUpdate', '_currencySymbol', 'driveGetFolderPhotos', 'rrShareOpenPhoto', 'findMaster', 'ERAS', 'state',
        sl64.slice(s0, s1) + ' return { sync: _sellSync, startup: rrSellSheetStartupSync };')(
        env.localStorage, env.driveRequest, env.sheetsClear, env.sheetsUpdate, env._currencySymbol, env.driveGetFolderPhotos, env.rrShareOpenPhoto, env.findMaster, env.ERAS, env.state);
      await api64.sync();
      const R = written.rows;
      const flat = JSON.stringify(R);
      ok('264 the title block carries the contact line Brad typed',
         R[0][0] === 'THE RAIL ROSTER — ITEMS FOR SALE' && /Brad Hale · 270-555/.test(R[1][0]));
      const r205 = R.find((r) => r[0] === '205-P');
      ok('264 the era column says what these ARE', r205 && r205[1] === 'Lionel Postwar');
      ok('264 the description is road + description + the variation\'s OWN words — no (var N) jargon',
         r205 && /Missouri Pacific — Alco Diesel — light blue shell painted blue/.test(r205[2]) &&
         !/\(var /.test(flat));
      ok('264 the SET-sale note rides the condition — a buyer can\'t mistake it for one unit',
         r205 && /7\/10 — Set sale: 205-P, 205-D/.test(r205[3]));
      ok('264 Box is spelled Yes or No, never silence',
         r205 && r205[4] === 'No' && R.find((r) => r[0] === '6462-50')[4] === 'Yes');
      // The discriminating case: PH2 EXISTS but Drive refused to open it —
      // a link to it would hit a request-access wall. It must stay off.
      ok('264 a photo link rides ONLY where opening the photo up succeeded',
         r205 && /drive\.google\.com\/file\/d\/PH1\/view/.test(r205[6]) &&
         R.find((r) => r[0] === '6462-50')[6] === '' &&
         R.find((r) => r[0] === '6656')[6] === '' &&
         opened.indexOf('PH1') >= 0 && opened.indexOf('PH2') >= 0);
      ok('264 the lookup carries the copy\'s OWN identity — era, maker, masterKey',
         preferSeen.every((p) => p && p.era === 'pw' && p.manufacturer === 'Lionel') &&
         preferSeen.some((p) => p.masterKey === 'pw|205|2'));
      ok('264 the clear range covers the widened sheet', written.cleared === 'Sheet1!A1:H1000');
      // ── the startup re-sync: exists, but never resurrects a trashed sheet ──
      written.rows = null;
      await api64.startup();
      ok('264 app start re-syncs the live list in the background', written.rows !== null);
      env.driveRequest = async () => ({ id: 'SHEET1', trashed: true });
      const api64b = new Function('localStorage', 'driveRequest', 'sheetsClear', 'sheetsUpdate', '_currencySymbol', 'driveGetFolderPhotos', 'rrShareOpenPhoto', 'findMaster', 'ERAS', 'state',
        sl64.slice(s0, s1) + ' return { startup: rrSellSheetStartupSync };')(
        env.localStorage, env.driveRequest, env.sheetsClear, env.sheetsUpdate, env._currencySymbol, env.driveGetFolderPhotos, env.rrShareOpenPhoto, env.findMaster, env.ERAS, env.state);
      written.rows = null;
      await api64b.startup();
      ok('264 a sheet the user trashed stays trashed — no silent resurrection', written.rows === null);
      // ── the panel offers the two new controls, never pre-filled ──
      ok('264 the panel has the contact input and the photo-links choice, no seeded value',
         /id="sell-contact-line"/.test(sl64) && /id="sell-photo-links"/.test(sl64) &&
         /rr_sell_contact/.test(sl64) && !/value="Brad/.test(sl64));
      // ── both start branches carry the hook ──
      const ad64 = fs.readFileSync(p64.join(__dirname, '..', 'app', 'app-data.js'), 'utf8');
      ok('264 the re-sync runs at BOTH app-start branches',
         (ad64.match(/setTimeout\(rrSellSheetStartupSync, 12000\)/g) || []).length === 2);
    })();

    // ═══════════════════════════════════════════════════════════
    // §265. v0.9.1318 — see the SELECTED variation on COTT while picking.
    //
    //   Brad: "we need a way to look at the different variations on cott."
